int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int a, b, c;
    if (!(std::cin >> a >> b >> c)) return 0;

    std::vector<int> sticks = {a, b, c};
    std::sort(sticks.begin(), sticks.end());

    // sorted: sticks[0] <= sticks[1] <= sticks[2]
    // Need sticks[0] + sticks[1] > sticks[2]
    if (sticks[0] + sticks[1] > sticks[2]) {
        std::cout << 0 << '\n';
    } else {
        // Need to increase sum of two smaller by (sticks[2] - (sticks[0] + sticks[1]) + 1)
        int needed = sticks[2] - (sticks[0] + sticks[1]) + 1;
        std::cout << needed << '\n';
    }

    return 0;
}
