    if (!(cin >> a >> b >> c)) return 0;

    vector<long long> sides = {a, b, c};
    sort(sides.begin(), sides.end());

    // For a triangle with positive area: sides[0] + sides[1] > sides[2]
    // If sides[2] >= sides[0] + sides[1], we need to increase sides[0] or sides[1] (or both)
    // Minimal minutes = sides[2] - (sides[0] + sides[1]) + 1
    long long needed = max(0LL, sides[2] - (sides[0] + sides[1]) + 1);

